resource funcApp 'Microsoft.Web/sites@2022-03-01' = {
  name: 'my-event-app'
  kind: 'functionapp'
  properties: {
    serverFarmId: appServicePlan.id
  }
}

resource eventSub 'Microsoft.EventGrid/eventSubscriptions@2023-06-01' = {
  name: 'blobCreatedSub'
  properties: {
    destination: {
      endpointType: 'WebHook'
      properties: {
        endpointUrl: '${funcApp.properties.defaultHostName}/api/BlobCreated'
      }
    }
    filter: {
      subjectBeginsWith: '/blobServices/default/containers/uploads/blobs/'
      includedEventTypes: ['Microsoft.Storage.BlobCreated']
    }
  }
}

[FunctionName("ProcessTelemetry")]
public async Task Run(
    [EventHubTrigger("telemetry-hub", Connection = "EventHubConnection")] EventData[] events,
    ILogger log)
{
    foreach (var eventData in events)
    {
        var payload = Encoding.UTF8.GetString(eventData.Body.ToArray());
        log.LogInformation("Event: {Payload}", payload);
        await _analytics.IngestAsync(eventData);
    }
}
